from pathlib import Path

PATH = Path('src/lib/financeRepository.js')
text = PATH.read_text()
marker = 'SAVINGS_COMPLETION_CORRECTION_REPAIR_V2'
if marker in text:
    print('Savings completion correction repair already patched')
    raise SystemExit(0)

old = '''    const [goals, expenses, wallets] = await Promise.all([\n      repository.getSavingsGoals(key, { includeDeleted: true }),\n      repository.getExpenses(key, { includeDeleted: true }),\n      repository.getWallets(key, { includeDeleted: true }),\n    ]);\n    const allGoals = Array.isArray(goals) ? goals : [];\n    const allExpenses = Array.isArray(expenses) ? expenses : [];\n    const walletMap = new Map('''
new = '''    const [goals, expenses, wallets, walletTransactions] = await Promise.all([\n      repository.getSavingsGoals(key, { includeDeleted: true }),\n      repository.getExpenses(key, { includeDeleted: true }),\n      repository.getWallets(key, { includeDeleted: true }),\n      repository.getWalletTransactions(key, { includeDeleted: true }),\n    ]);\n    const allGoals = Array.isArray(goals) ? goals : [];\n    const allExpenses = Array.isArray(expenses) ? expenses : [];\n    const allWalletTransactions = Array.isArray(walletTransactions) ? walletTransactions : []; // SAVINGS_COMPLETION_CORRECTION_REPAIR_V2\n    const walletMap = new Map('''
if old not in text:
    raise SystemExit('completion repair Promise.all anchor missing')
text = text.replace(old, new, 1)

old = '''      const activity = getSavingsCompletionActivity(goal);\n      if (!activity) continue;\n      if (allExpenses.some((expense) => savingsExpenseMatchesGoal(expense, goal, activity))) continue;\n\n      const goalId = getSavingsGoalId(goal);\n      const walletId = getSavingsGoalWalletId(goal, activity);\n      const amount = Math.abs(toNumber(activity?.amount));\n      const wallet = walletMap.get(walletId);\n      if (!goalId || !walletId || !wallet || amount <= 0) continue;\n\n      const currentBalance = getWalletBalance(wallet);\n      // Never create a negative balance during automatic legacy repair.\n      if (currentBalance + 0.0001 < amount) continue;'''
new = '''      const goalId = getSavingsGoalId(goal);\n      let activity = getSavingsCompletionActivity(goal);\n\n      const historicalCorrection = allWalletTransactions.find((transaction) => {\n        if (!transaction || transaction?.deletedAt || transaction?.deleted_at) return false;\n        const sourceType = String(transaction?.source_type || transaction?.sourceType || \"\").trim().toLowerCase();\n        const type = String(transaction?.type || \"\").trim().toLowerCase();\n        if (sourceType !== \"savings_wallet_reconciliation\" || type !== \"balance_correction\") return false;\n        let details = transaction?.details || {};\n        if (typeof details === \"string\") {\n          try { details = JSON.parse(details); } catch { details = {}; }\n        }\n        return goalId && String(details?.savings_goal_id || details?.savingsGoalId || \"\").trim() === goalId;\n      }) || null;\n\n      if (!activity && historicalCorrection) {\n        let details = historicalCorrection?.details || {};\n        if (typeof details === \"string\") {\n          try { details = JSON.parse(details); } catch { details = {}; }\n        }\n        activity = {\n          type: \"complete\",\n          amount: Math.abs(toNumber(details?.adjustment || historicalCorrection?.amount)),\n          storageWalletId: historicalCorrection?.wallet_id || historicalCorrection?.walletId || \"\",\n          createdAt: historicalCorrection?.created_at || historicalCorrection?.createdAt || null,\n        };\n      }\n\n      if (!activity) continue;\n      if (allExpenses.some((expense) => savingsExpenseMatchesGoal(expense, goal, activity))) continue;\n\n      const walletId = getSavingsGoalWalletId(goal, activity);\n      const amount = Math.abs(toNumber(activity?.amount));\n      const wallet = walletMap.get(walletId);\n      if (!goalId || !walletId || !wallet || amount <= 0) continue;\n\n      const currentBalance = getWalletBalance(wallet);\n\n      // Historical Savings Goal reconciliation used to write the wallet balance directly\n      // and then insert a synthetic Balance Correction row. If that direct correction\n      // already landed, never deduct the same money again. If the transaction exists\n      // but the wallet is still at its pre-correction balance, create the missing\n      // canonical completion expense now so the real wallet ledger finally changes.\n      if (historicalCorrection) {\n        let details = historicalCorrection?.details || {};\n        if (typeof details === \"string\") {\n          try { details = JSON.parse(details); } catch { details = {}; }\n        }\n        const nextBalance = toNumber(details?.next_balance ?? details?.nextBalance);\n        const previousBalance = toNumber(details?.previous_balance ?? details?.previousBalance);\n        if (Number.isFinite(nextBalance) && Math.abs(currentBalance - nextBalance) <= 0.0001) {\n          continue;\n        }\n        if (Number.isFinite(previousBalance) && Math.abs(currentBalance - previousBalance) > 0.0001 && currentBalance + 0.0001 < amount) {\n          continue;\n        }\n      }\n\n      // Never create a negative balance during automatic legacy repair.\n      if (currentBalance + 0.0001 < amount) continue;'''
if old not in text:
    raise SystemExit('completion activity repair anchor missing')
text = text.replace(old, new, 1)
PATH.write_text(text)
print('Savings completion correction repair patched')
